//! Actions-only real original Common read -> received WRITE -> journal/Join.
//! No original SDK library, device, Provider API or paid traffic is used.
use super::*;
use n::{im_sync_policy::NativeImSyncConfig,im_receipt_policy::NativeImReceiptConfig};
#[path="im_read_status_account_tests.rs"]
mod manual_read_status;
fn config(root:&str,port:u16,writes:bool)->AccountConfig{let mut c=super::config(root,port,3000);c.profile.im_sync=Some(NativeImSyncConfig{receive:true});c.profile.im_receipts=writes.then_some(NativeImReceiptConfig{set_received:true});c}
fn status(target:i64,time:i64)->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(1).unwrap();w.bytes(b"1_2").unwrap();let t=target.to_string();w.properties(&[RpcProperty{key:n::im_status::PEER_READ,value:b"0"},RpcProperty{key:n::im_status::LATEST,value:t.as_bytes()}]).unwrap();w.i64(time).unwrap();w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn records(start:i64,count:u32)->Vec<u8>{let mut w=Writer::new();w.boolean(true).unwrap();w.u32(count).unwrap();for i in start..start+i64::from(count){w.i64(i).unwrap();w.i64(1234567890123).unwrap();w.bytes(b"fixture-private-uid").unwrap();w.bytes(b"Text").unwrap();w.bytes(br#"{"text":"original IM text","userData":"private-not-public"}"#).unwrap();w.properties(&[RpcProperty{key:b"../never-written",value:b"attachment-bytes"}]).unwrap();w.properties(&[]).unwrap();}w.bytes(b"").unwrap();w.finish().expose_to_transport().to_vec()}
fn receipt(db:&crate::platform::db::Database)->(i64,Option<i32>,i64){db.with_conn(|c|c.query_row("SELECT state,request_id,target_index FROM app_voice_im_read_receipts",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).map_err(|_|"fixture")).unwrap()}
async fn poll(peer:&mut CommonPeer,p:&[u8]){let r=decode_request(&p[1..]).unwrap();assert_eq!(r.method,n::rpc_batch::SWAP_CALLS_METHOD.as_bytes(),"no receipt replay or unrelated write");let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");assert_eq!(a.bytes().unwrap(),b"fixture-original-selector");let p=n::rpc_batch::read_payload(&mut a).unwrap();assert!(p.requests.is_empty());peer.send(&[reply(r.call_id,&n::runtime_backend::tests::swap_result(None,true,p.fields))]).await;}
async fn query(peer:&mut CommonPeer,method:&str)->Vec<u8>{loop{let p=peer.next().await.unwrap();assert_eq!(p[0],0);let r=decode_request(&p[1..]).unwrap();if r.method==n::rpc_batch::SWAP_CALLS_METHOD.as_bytes(){poll(peer,&p).await;continue;}assert_eq!(r.method,method.as_bytes());assert_eq!(r.metadata.len(),2);assert_eq!(r.metadata.iter().find(|v|v.key==b"id").unwrap().value,b"#Group");assert_eq!(r.metadata.iter().find(|v|v.key==b"token").unwrap().value,b"fixture-auth");return p;}}
async fn login_host(peer:&mut CommonPeer){let p=peer.next().await.unwrap();let r=decode_request(&p[1..]).unwrap();peer.send(&[reply(r.call_id,&login_result())]).await;let(_,flag)=hosting_call(peer).await;assert_eq!(flag,b"4");}
async fn refresh(peer:&mut CommonPeer,target:i64,time:i64){let p=query(peer,n::im_status::REFRESH_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"fixture-user");peer.send(&[reply(r.call_id,&status(target,time))]).await;}
async fn receive(peer:&mut CommonPeer,start:i64,count:u32){let p=query(peer,n::im_data::RECV_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"P2P/1_2");assert_eq!(a.i64().unwrap(),start);assert_eq!(a.u32().unwrap(),count);a.finish().unwrap();peer.send(&[reply(r.call_id,&records(start,count))]).await;}
async fn write(peer:&mut CommonPeer,target:i64)->i32{let p=query(peer,n::im_data::SET_READ_METHOD).await;let r=decode_request(&p[1..]).unwrap();let mut a=Reader::versioned(r.arguments).unwrap();assert_eq!(a.bytes().unwrap(),b"P2P/1_2");assert_eq!(a.i64().unwrap(),target);a.finish().unwrap();r.call_id}
fn response(id:i32,yes:bool,code:u32)->Vec<u8>{let mut w=Writer::new();w.boolean(yes).unwrap();w.bytes(b"").unwrap();let rpc=encode_reply(id,code,w.finish().expose_to_transport()).unwrap();let mut p=vec![1];p.extend_from_slice(rpc.expose_to_transport());p}
#[tokio::test]
async fn received_account_installed_write_chain_has_uncertainty_before_peer_io_and_matched_ack_before_next_gap(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,12,1).await;receive(&mut peer,1,10).await;let id=write(&mut peer,10).await;assert_eq!(receipt(&db),(0,Some(id),10));assert_eq!(count(&db),10);peer.send(&[response(id,true,0)]).await;
        receive(&mut peer,11,2).await;assert_eq!(receipt(&db),(1,Some(id),10));let id=write(&mut peer,12).await;assert_eq!(receipt(&db),(0,Some(id),12));assert_eq!(count(&db),12);peer.send(&[response(id,true,0),hint(91,99,12)]).await;next_reply(&mut peer,91,true).await;assert_eq!(receipt(&db),(1,Some(id),12));done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();assert_eq!(manager.im_messages(&line,16).unwrap().len(),12);assert!(manager.messages(&line,16).unwrap().is_empty());assert!(temp.database.get_call_history_for_line(&line,16,0).unwrap().is_empty());assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());
}).await;}
#[tokio::test]
async fn received_account_online_contiguous_message_writes_once_and_deleted_duplicate_does_not_resurrect_or_replay(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(ready,seen)=tokio::sync::oneshot::channel();let(replay,wait)=tokio::sync::oneshot::channel();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,0,1).await;peer.send(&[message(91,1,true)]).await;next_reply(&mut peer,91,true).await;let id=write(&mut peer,1).await;assert_eq!(receipt(&db),(0,Some(id),1));peer.send(&[response(id,true,0),hint(92,99,1)]).await;next_reply(&mut peer,92,true).await;assert_eq!(receipt(&db),(1,Some(id),1));ready.send(()).unwrap();wait.await.unwrap();peer.send(&[message(93,1,true)]).await;next_reply(&mut peer,93,true).await;assert_eq!(receipt(&db),(1,Some(id),1));assert_eq!(count(&db),1);done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(seen).await.unwrap();let rows=manager.im_messages(&line,16).unwrap();assert_eq!(rows.len(),1);assert!(manager.delete_im_message(&line,rows[0].id).unwrap());replay.send(()).unwrap();bounded(finished).await.unwrap();assert!(manager.im_messages(&line,16).unwrap().is_empty());assert_eq!(temp.database.get_recent_app_events(Some(&line),16).unwrap().iter().filter(|e|e.event_type=="im.received").count(),1);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
#[tokio::test]
async fn received_account_readonly_sync_default_never_writes_or_persists_receipt_marker(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,false),100).await.unwrap().account;let line=account.line_id.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,1,1).await;receive(&mut peer,1,1).await;peer.send(&[hint(91,99,1)]).await;next_reply(&mut peer,91,true).await;done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();let rows:i64=temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_read_receipts",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(rows,0);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}).await;}
async fn rejected(code:u32){
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{let mut peer=CommonPeer::open(listener,server).await;login_host(&mut peer).await;refresh(&mut peer,1,1).await;receive(&mut peer,1,1).await;let id=write(&mut peer,1).await;assert_eq!(receipt(&db),(0,Some(id),1));peer.send(&[response(id,false,code),hint(91,99,1)]).await;next_reply(&mut peer,91,true).await;assert_eq!(receipt(&db),(2,Some(id),1));done.send(()).unwrap();finish_account(&mut peer).await;}).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();bounded(async{while manager.get(&line,100).await.unwrap().last_error!=Some("app_account_im_receipt_rejected"){tokio::time::sleep(Duration::from_millis(5)).await;}}).await;let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert_eq!(view.last_error,Some("app_account_im_receipt_rejected"));assert_eq!(manager.im_messages(&line,16).unwrap().len(),1);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();
}
#[tokio::test]async fn received_account_original_false_reply_is_known_negative_and_not_replayed(){Box::pin(rejected(0)).await;}
#[tokio::test]async fn received_account_original_version_error_is_known_negative_and_never_auto_resubmits(){Box::pin(rejected(65537)).await;}
#[tokio::test]
async fn received_account_unknown_timeout_joins_old_io_and_blocks_new_nonce_write_after_explicit_restart(){Box::pin(async{
    let cert=Certificates::generate("IP:127.0.0.1");let listener=TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let server=cert.server_config(&TLS13);let temp=TempDatabase::new();let manager=AccountManager::new(temp.database.clone());let account=manager.create(config(&cert.root,port,true),100).await.unwrap().account;let line=account.line_id.clone();let db=temp.database.clone();let(sent,observed)=tokio::sync::oneshot::channel();let(done,finished)=tokio::sync::oneshot::channel();
    let serving=tokio::spawn(async move{bounded(async move{
        let original_listener=listener.into_std().unwrap();let second=TcpListener::from_std(original_listener.try_clone().unwrap()).unwrap();let first=TcpListener::from_std(original_listener).unwrap();
        let mut peer=CommonPeer::open(first,server.clone()).await;login_host(&mut peer).await;refresh(&mut peer,1,1).await;receive(&mut peer,1,1).await;let id=write(&mut peer,1).await;assert_eq!(receipt(&db),(0,Some(id),1));sent.send(()).unwrap();while let Some(p)=peer.next().await{poll(&mut peer,&p).await;}assert_eq!(receipt(&db),(0,Some(id),1));
        let mut peer=CommonPeer::open(second,server).await;login_host(&mut peer).await;refresh(&mut peer,2,2).await;receive(&mut peer,2,1).await;peer.send(&[hint(91,99,2)]).await;next_reply(&mut peer,91,true).await;assert_eq!(receipt(&db),(0,Some(id),1),"unknown original write is not repeated under the new native login/run");done.send(()).unwrap();finish_account(&mut peer).await;
    }).await});
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(observed).await.unwrap();bounded(async{loop{if manager.get(&line,100).await.unwrap().phase=="disconnected"{break;}tokio::time::sleep(Duration::from_millis(5)).await;}}).await;
    assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);assert!(!temp.database.with_conn(|c|n::account_runs::ownership_pending(c,&line)).unwrap());assert_eq!(receipt(&temp.database).0,0);
    bounded(manager.start(&line,account.revision,100)).await.unwrap();bounded(finished).await.unwrap();bounded(async{while manager.get(&line,100).await.unwrap().last_error!=Some("app_account_im_receipt_uncertain"){tokio::time::sleep(Duration::from_millis(5)).await;}}).await;let view=manager.get(&line,100).await.unwrap();assert_eq!(view.phase,"hosted");assert_eq!(view.last_error,Some("app_account_im_receipt_uncertain"));assert_eq!(manager.im_messages(&line,16).unwrap().len(),2);assert!(!bounded(manager.stop(&line,account.revision,100)).await.unwrap().io_cleanup_required);bounded(serving).await.unwrap();assert_eq!(receipt(&temp.database).0,0);
}).await;}
